'use strict';
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uuid=()=>crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2);
const ASSEMBLY_NAME='Assemblea Parlamentare Stato di Seborg - FERRIOLI.EU';
const IS_BOARD_TAB=new URLSearchParams(location.search).get('view')==='tabellone';
const firebaseConfig=()=>read(KEYS.config,null)||window.ASSEMBLY_FIREBASE_CONFIG;
const KEYS={display:'seborg-display-v1',state:'aula-state-v1',config:'aula-firebase-v1',ballots:'aula-ballots-v1'};
const OPTIONS=[['yes','Favorevoli','Sì','#28755c'],['no','Contrari','No','#b34b4b'],['abstain','Astenuti','Astensione','#b69150'],['blank','Bianche','Bianca','#a5b1bc'],['null','Nulle','Nulla','#8b70a4']];
const phases=['preparation','open','closed','pending','published'], phaseNames=['Preparazione','Votazione aperta','Votazione chiusa','In attesa dei risultati','Risultati pubblicati'];
const roleOf=email=>email?.toLowerCase()==='jacopo@ferrioli.eu'?'president':['amministrazione.generale@cas.ferrioli.eu','amministrazione@ferrioli.eu'].includes(email?.toLowerCase())?'secretary':'voter';
const roleNames={president:'Presidente',secretary:'Segretario',voter:'Votante',viewer:'Visualizzatore'};
const dateStr=v=>new Date(v).toLocaleDateString('it-IT',{day:'numeric',month:'long',year:'numeric'}), timeStr=v=>new Date(v).toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit'});
function initial(){return {id:uuid(),title:ASSEMBLY_NAME,number:1,date:Date.now(),status:'ready',started:null,ended:null,resumeAt:null,defaultMinutes:3,agenda:[],currentAgenda:null,members:[],queue:[],speaker:null,speeches:[],motions:[],selectedMotion:null,log:[],notes:''};}
function read(key,def){try{return JSON.parse(localStorage.getItem(key))??def;}catch{return def;}}
let state=read(KEYS.state,null)||initial(), ballots=read(KEYS.ballots,{}), user=null, role=null, page='dashboard', board=IS_BOARD_TAB, demo=false, cloud=null, auth=null, fb=null, unsubscribe=null, unballots=null, sync='Locale', modalKind='', allowVoteOverlay=true;
const manage=()=>role==='president'||role==='secretary', preside=()=>role==='president', motion=()=>state.motions.find(m=>m.id===state.selectedMotion), activeAgenda=()=>state.agenda.find(a=>a.id===state.currentAgenda);
const counts=()=>{const present=state.members.filter(m=>m.present);return {total:state.members.length,present:present.length,absent:state.members.length-present.length,eligible:present.filter(m=>m.eligible).length,nonVoting:present.filter(m=>!m.eligible).length,electorate:state.members.filter(m=>m.eligible).length};};
function log(text){state.log.push({at:Date.now(),text});}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').classList.remove('show'),4000);}
async function save(){localStorage.setItem(KEYS.state,JSON.stringify(state));render();if(cloud){try{await fb.set(fb.ref(cloud,'aula/session'),state);}catch(e){sync='Sincronizzazione non riuscita';toast('Dati salvati solo su questo dispositivo: '+e.message);render();}}}
function normalize(s){if(['Assemblea parlamentare','Assemblea dei rappresentanti'].includes(s.title))s.title=ASSEMBLY_NAME;for(const k of ['agenda','members','queue','speeches','motions','log'])s[k]=s[k]||[];return s;}
// Il tabellone legge una proiezione della seduta, senza modificare la regia.
function displaySnapshot(){const view=JSON.parse(JSON.stringify(state));view.log=[];view.speeches=[];view.notes='';for(const m of view.motions){if(m.phase!=='published'){delete m.result;delete m.rollcall;}}return {state:view,updatedAt:Date.now(),sync};}
function publishDisplay(){if(user&&!IS_BOARD_TAB)localStorage.setItem(KEYS.display,JSON.stringify(displaySnapshot()));}
function loadDisplay(){const saved=read(KEYS.display,null);if(saved?.state){state=normalize(saved.state);sync=saved.sync||'Tabellone collegato';}else{state=initial();sync='Apri la regia per collegare il tabellone';}}
function openBoard(){publishDisplay();const url=new URL(location.href);url.search='?view=tabellone';url.hash='';const target=window.open(url.href,'seborg-tabellone');if(!target)toast('Consenti l’apertura della nuova scheda per mostrare il tabellone.');else target.focus();}
if(IS_BOARD_TAB){loadDisplay();user={uid:'display',email:'',displayName:'Tabellone'};role='viewer';document.title='Tabellone — Stato di Seborg | FERRIOLI.EU';}
window.addEventListener('storage',e=>{if(IS_BOARD_TAB){if(e.key===KEYS.display){loadDisplay();render();}return;}if(!demo&&cloud)return;if(e.key===KEYS.state){state=normalize(read(KEYS.state,state));render();}if(e.key===KEYS.ballots){ballots=read(KEYS.ballots,{});render();}});
const btn=(text,action,cls='',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
function field(label,name,type='text',value='',extra=''){return `<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`;}
const area=(label,name,value='')=>`<div class="field full"><label for="f-${name}">${label}</label><textarea id="f-${name}" name="${name}">${esc(value)}</textarea></div>`;
const select=(label,name,options,value)=>`<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${options.map(([v,t])=>`<option value="${v}" ${v===value?'selected':''}>${t}</option>`).join('')}</select></div>`;
const check=(label,name,checked=true)=>`<label class="check"><input type="checkbox" name="${name}" ${checked?'checked':''}>${label}</label>`;
function openModal(title,body,submitLabel,submitAction,wide=false){modalKind=submitAction;$('#overlay').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${title}</h2>${btn('✕','close','ghost','aria-label="Chiudi"')}</div><form id="modal-form" data-submit="${submitAction}">${body}<div id="form-error" class="error" role="alert"></div><div class="modal-actions">${btn('Annulla','close','','type="button"')}<button type="submit" class="primary">${submitLabel}</button></div></form></section></div>`;setTimeout(()=>$('#modal-form input, #modal-form textarea')?.focus(),0);}
function closeModal(){modalKind='';$('#overlay').innerHTML='';renderOverlay();}
function formError(t){$('#form-error').textContent=t;}
function enterDemo(){demo=true;user={email:'demo@locale',uid:'demo-president',displayName:'Presidenza demo'};role='president';sync='Demo · solo questo browser';render();}
function loginScreen(){const config=firebaseConfig();$('#app').innerHTML=`<div class="login"><section class="login-art"><div><div class="brand"><span class="emblem">▥</span>Seborg</div><div class="brand-sub">ASSEMBLEA PARLAMENTARE · FERRIOLI.EU</div></div><div><div class="eyebrow" style="color:#b59a69;margin-bottom:20px">ORDINE · DIALOGO · DECISIONE</div><h1>Assemblea<br>Parlamentare<br>Stato di Seborg.</h1><p>Presidenza, discussione e deliberazioni.<br>Il portale dei lavori parlamentari di FERRIOLI.EU.</p></div><div class="hemicycle">◜◠◝</div><small>STATO DI SEBORG — FERRIOLI.EU</small></section><section class="login-form"><div class="login-box"><div class="eyebrow">STATO DI SEBORG · FERRIOLI.EU</div><h2>Accedi al Parlamento</h2><p class="muted">Il tuo account determina il ruolo nella seduta.</p><form id="login-form">${field('Email','email','email','','required autocomplete="username"')}${field('Password','password','password','','required autocomplete="current-password"')}<div class="error" id="login-error"></div><button class="primary" type="submit" ${config?'':'disabled'}>Accedi con Firebase →</button></form>${btn('Prova la presidenza · demo locale','demo')}${btn(config?'Modifica configurazione Firebase':'Collega il tuo progetto Firebase','config','ghost')}<div class="login-foot">${config?'FERRIOLI.EU · Accesso email e password':'Firebase non ancora collegato. La demo è pronta per il testing.'}<br>Ottimizzato per desktop e proiezione.</div></div></section></div>`;}
function render(){if(!user){loginScreen();return;}state=normalize(state);publishDisplay();const c=counts(),status=state.status==='active'?'Seduta in corso':state.status==='suspended'?'Seduta sospesa':state.status==='ended'?'Seduta conclusa':'Da aprire';$('#app').innerHTML=`<div class="shell ${board?'board':''}"><aside class="sidebar"><div class="brand"><span class="emblem">▥</span>Seborg</div><div class="brand-sub">PARLAMENTO · FERRIOLI.EU</div><nav class="nav">${[['dashboard','▦','Regia della seduta'],['agenda','≡','Ordine del giorno'],['votes','◉','Votazioni'],['members','♧','Assemblea'],['minutes','▤','Verbale'],['settings','⚙','Impostazioni']].map(([p,i,t])=>btn(`<span class="icon">${i}</span>${t}`,'nav',page===p?'active':'',`data-page="${p}"`)).join('')}</nav><div class="sidebar-bottom"><div class="notice" style="background:#ffffff05;border-color:#ffffff12;color:#9fb1bb;font-size:10px">${demo?'AMBIENTE DI PROVA<br>Dati salvati in questo browser.':'SESSIONE CONDIVISA<br>Accesso verificato con Firebase.'}</div><div class="identity"><div class="avatar">${role==='president'?'P':role==='secretary'?'S':'V'}</div><div><strong>${roleNames[role]}</strong><br><small>${demo?'Modalità dimostrativa':esc(user.email)}</small></div></div><div class="connection">● ${esc(sync)}</div>${btn('Esci dall’account','logout','ghost','style="color:#a7b8c1;font-size:11px;padding:0"')}</div></aside><main class="main"><header class="topbar"><div class="crumb">Assemblea <span style="margin:0 10px;color:#bcc3c5">/</span> Seduta n. ${state.number}</div><div class="top-actions"><span class="badge ${state.status==='active'?'':state.status==='suspended'?'amber':'neutral'}">${status}</span><span class="clock" id="clock"></span>${btn('↗ Apri tabellone','board','small','title="Apri in una scheda separata"')}</div></header><div class="content">${board?boardView():({dashboard:dashboard,agenda:agendaView,votes:votesView,members:membersView,minutes:minutesView,settings:settingsView}[page]||dashboard)()}<footer class="footnote"><span>SEBORG · FERRIOLI.EU / ${board?'TABELLONE DELL’ASSEMBLEA':roleNames[role].toUpperCase()}</span><span>${dateStr(state.date)} · Seduta ${String(state.number).padStart(2,'0')}</span></footer></div></main></div>`;tick();renderOverlay();}
function head(title,subtitle,actions=''){return `<div class="page-head"><div><div class="eyebrow" style="margin-bottom:10px">SEDUTA N. ${String(state.number).padStart(2,'0')} / ${dateStr(state.date)}</div><h1 class="serif">${title}</h1><p>${subtitle}</p></div><div class="actions">${actions}</div></div>`;}
function dashboard(){const c=counts();return head('Presidenza dell’Assemblea',esc(state.title),preside()?(state.status==='ready'?btn('Apri la seduta','start','primary'):state.status==='ended'?btn('Seduta conclusa','none','','disabled'):btn('Ⅱ Sospendi','suspend')+btn('Concludi seduta','end','primary')):'')+`<div class="stats">${[[c.present,'Presenti in aula',`${c.absent} assenti su ${c.total} componenti`],[c.eligible,'Con diritto di voto',`${c.nonVoting} presenti senza diritto`],[state.agenda.length,'Punti all’ordine del giorno',`${state.agenda.filter(a=>a.done).length} punti conclusi`],[state.motions.filter(m=>m.phase==='published').length,'Votazioni concluse',`${state.motions.length} proposte depositate`]].map(([n,t,f])=>`<div class="stat"><div class="stat-title">${t}<span>↗</span></div><div class="stat-value">${n}</div><div class="stat-foot">${f}</div></div>`).join('')}</div><div class="grid-main"><div>${speakerCard()}${queueCard()}</div><div>${agendaCard()}${motionCard(true)}</div></div>`;}
function speakerCard(){const s=state.speaker;return `<section class="card speech"><div class="card-head"><span class="eyebrow">${s?'INTERVENTO IN CORSO':'GESTIONE DELLA PAROLA'}</span><span class="badge">${s?(s.running?'Ha la parola':'Timer in pausa'):'In ascolto'}</span></div><div class="speech-main"><div class="eyebrow">${s?'LA PRESIDENZA DÀ LA PAROLA A':'IL PROSSIMO INTERVENTO'}</div><div class="speaker">${s?esc(s.name):'L’aula è in ascolto'}</div><div class="seat">${s?'Posto '+esc(s.seat||'—'):'Assegna la parola per iniziare'}</div><div class="timer" id="speech-timer">${s?'00:00':'— : —'}</div><div class="timer-hint" id="timer-hint">TEMPO A DISPOSIZIONE</div><div class="progress"><div id="timer-progress" style="width:100%"></div></div></div>${preside()&&!board?`<div class="speech-controls">${s?btn(s.running?'Ⅱ Pausa':'▷ Riprendi','timer-toggle')+btn('+ 30 sec','timer-add')+btn('Termina intervento','speech-end','primary'):btn('＋ Dai la parola','give-floor','primary',state.status!=='active'?'disabled':'')}</div>`:''}</section>`;}
function queueCard(){return `<section class="card"><div class="card-head"><h2>Prossimi interventi <small> / ${state.queue.length}</small></h2>${manage()?btn('＋ Aggiungi','queue-add','small'):''}</div>${state.queue.length?`<div class="rows">${state.queue.map((q,i)=>`<div class="row"><span class="row-num">${String(i+1).padStart(2,'0')}</span><div class="row-main"><strong>${esc(q.name)}</strong><small>Posto ${esc(q.seat||'—')} · ${q.minutes} min</small></div>${preside()?btn('Dai la parola →','queue-start','small',`data-id="${q.id}" ${state.speaker||state.status!=='active'?'disabled':''}`):''}${manage()?btn('×','queue-remove','ghost',`data-id="${q.id}" aria-label="Rimuovi intervento"`):''}</div>`).join('')}</div>`:'<div class="empty">Nessun intervento prenotato.<br>La presidenza può assegnare la parola a un posto.</div>'}</section>`;}
function agendaCard(){return `<section class="card"><div class="card-head"><h2>Ordine del giorno</h2>${btn('Vedi tutto ↗','nav','ghost small','data-page="agenda"')}</div>${state.agenda.length?state.agenda.slice(0,4).map((a,i)=>`<div class="row ${a.id===state.currentAgenda?'current':''}"><span class="row-num">${String(i+1).padStart(2,'0')}</span><div class="row-main"><strong>${esc(a.title)}</strong><small>${a.done?'Concluso':a.id===state.currentAgenda?'In discussione':'Da discutere'}</small></div>${a.id===state.currentAgenda?'<span style="color:var(--gold)">●</span>':a.done?'✓':''}</div>`).join(''):'<div class="empty">Prepara i temi della seduta.</div>'}${manage()?btn('＋ Aggiungi punto','agenda-add','small','style="margin-top:16px;width:100%"'):''}</section>`;}
function motionCard(compact=false){const m=motion();if(!m)return `<section class="card"><div class="card-head"><h2>Votazione</h2><span class="eyebrow">NESSUNA IN CORSO</span></div><div class="empty">Le decisioni dell’assemblea<br>prendono forma qui.</div>${manage()?btn('＋ Prepara una mozione','motion-add','primary','style="width:100%"'):''}</section>`;return `<section class="card"><div class="card-head"><span class="eyebrow">${m.parent?'EMENDAMENTO':'MOZIONE'} ${String(state.motions.indexOf(m)+1).padStart(2,'0')}</span><span class="badge ${m.phase==='open'?'':'neutral'}">${phaseNames[phases.indexOf(m.phase)]}</span></div><h2 class="motion-title">${esc(m.title)}</h2><p class="motion-text">${esc(compact?m.text.slice(0,160)+(m.text.length>160?'…':''):m.text)}</p><div class="meta"><div><small>PRESENTATORE</small>${esc(m.presenter||'—')}</div><div><small>MAGGIORANZA</small>${esc(ruleLabel(m))}</div></div>${!compact?`<div class="meta section-gap"><div><small>FIRMATARI</small>${esc(m.signers||'—')}</div><div><small>MODALITÀ</small>${m.mode==='manual'?'Scrutinio manuale':'Voto dai dispositivi'} · ${m.secret?'segreto':'palese'}</div></div>`:''}<div class="flow">${phases.map((p,i)=>`<span class="${i<=phases.indexOf(m.phase)?'done':''}"></span>`).join('')}</div>${m.phase==='published'?resultsHTML(m):`<div class="notice">${m.phase==='open'?'Votazione aperta. I conteggi restano nascosti a tutti.':m.phase==='pending'?'Scrutinio in corso. I risultati non sono ancora pubblicati.':m.phase==='closed'?'Voto concluso. Passa allo scrutinio per inserire i risultati.':'La proposta è pronta per essere sottoposta all’assemblea.'}</div>`}<div class="actions section-gap">${motionActions(m,compact)}</div></section>`;}
function motionActions(m,compact){if(board)return '';let out='';if(preside()){if(m.phase==='preparation')out+=btn('Apri votazione →','vote-open','primary',state.status!=='active'?'disabled':'');if(m.phase==='open')out+=btn('Chiudi votazione','vote-close','primary',state.status!=='active'?'disabled':'');if(m.phase==='closed')out+=btn('Avvia scrutinio','vote-pending','primary');if(m.phase==='pending'&&m.result)out+=btn('Pubblica risultati','vote-publish','primary');}if(manage()&&m.phase==='pending')out+=btn(m.result?'Modifica risultati':'Inserisci risultati','results','');if(!compact&&manage()&&m.phase==='preparation')out+=btn('Modifica','motion-edit','','data-id="'+m.id+'"');if(compact)out+=btn('Dettagli ↗','nav','ghost small','data-page="votes"');if(m.phase==='open'&&m.mode==='digital'&&role==='voter')out+=btn('Esprimi il voto','vote-show','primary');return out;}
function agendaView(){return head('Ordine del giorno','Organizza la discussione, un punto alla volta.',manage()?btn('＋ Nuovo punto','agenda-add','primary'):'')+`<section class="card">${state.agenda.length?state.agenda.map((a,i)=>`<div class="row ${a.id===state.currentAgenda?'current':''}"><span class="row-num">${String(i+1).padStart(2,'0')}</span><div class="row-main"><strong>${esc(a.title)}</strong><small>${esc(a.description||'')} ${a.done?' · Concluso':a.id===state.currentAgenda?' · In discussione':''}</small></div><div class="actions">${preside()?btn('Discuti','agenda-discuss','small',`data-id="${a.id}" ${state.status!=='active'||a.done?'disabled':''}`)+btn('Concludi','agenda-done','small',`data-id="${a.id}" ${a.done?'disabled':''}`):''}${manage()?btn('Modifica','agenda-edit','small',`data-id="${a.id}"`):''}</div></div>`).join(''):'<div class="empty">L’ordine del giorno è ancora vuoto. Aggiungi il primo punto.</div>'}</section>`;}
function votesView(){return head('Votazioni','Mozioni, emendamenti e decisioni dell’assemblea.',manage()?btn('＋ Nuova mozione','motion-add','primary'):'')+`<div class="grid-main"><div>${motionCard()}${motion()&&manage()?btn('＋ Aggiungi emendamento','amendment-add','','style="margin-bottom:24px"'):''}</div><section class="card" style="align-self:start"><div class="card-head"><h2>Proposte depositate</h2><small>${state.motions.length}</small></div>${state.motions.length?state.motions.map((m,i)=>`<div class="row"><span class="row-num">${String(i+1).padStart(2,'0')}</span><div class="row-main"><strong>${m.parent?'↳ ':''}${esc(m.title)}</strong><small>${phaseNames[phases.indexOf(m.phase)]}</small></div>${btn(m.id===state.selectedMotion?'●':'Apri','motion-select','small',`data-id="${m.id}"`)}</div>`).join(''):'<div class="empty">Nessuna proposta depositata.</div>'}</section></div>`;}
function membersView(){const c=counts();return head('L’assemblea','Componenti, presenze e diritto di voto.',manage()?btn('＋ Aggiungi membro','member-add','primary'):'')+`<div class="stats">${[[c.present,'Presenti'],[c.absent,'Assenti'],[c.eligible,'Presenti aventi diritto'],[c.nonVoting,'Presenti senza diritto']].map(([n,t])=>`<div class="stat"><div class="stat-title">${t}</div><div class="stat-value">${n}</div></div>`).join('')}</div><section class="card"><div class="table-wrap"><table><thead><tr><th>Posto</th><th>Nome / email</th><th>Presente</th><th>Diritto di voto</th><th></th></tr></thead><tbody>${state.members.map(m=>`<tr><td>${esc(m.seat||'—')}</td><td><strong>${esc(m.name||m.email)}</strong>${m.name&&m.email?'<br><small>'+esc(m.email)+'</small>':''}</td><td><input aria-label="Presenza di ${esc(m.name||m.email)}" type="checkbox" data-member="${m.id}" data-prop="present" ${m.present?'checked':''} ${manage()?'':'disabled'}></td><td><input aria-label="Diritto di voto di ${esc(m.name||m.email)}" type="checkbox" data-member="${m.id}" data-prop="eligible" ${m.eligible?'checked':''} ${manage()?'':'disabled'}></td><td>${manage()?btn('Modifica','member-edit','small',`data-id="${m.id}"`):''}</td></tr>`).join('')}</tbody></table>${state.members.length?'':'<div class="empty">Aggiungi i componenti per calcolare presenze, quorum e maggioranze.</div>'}</div></section>`;}
function settingsView(){return head('Impostazioni','Le poche regole che servono alla tua assemblea.')+`<div class="grid-main"><section class="card"><h2>La seduta</h2><form data-submit="settings" class="stack">${field('Nome dell’assemblea','title','text',state.title,'required')}${field('Numero della seduta','number','number',state.number,'min="1" required')}${field('Durata predefinita degli interventi (minuti)','minutes','number',state.defaultMinutes,'min="0.1" step="0.1" required')}<button class="primary" ${manage()?'':'disabled'}>Salva impostazioni</button></form><hr class="divider">${preside()?btn('Nuova seduta vuota','new-session','danger'):''}<p class="muted" style="font-size:11px;margin-top:12px">Prima di iniziarne un’altra, salva il verbale della seduta corrente.</p></section><div><section class="card"><h2>Connessione</h2><p class="muted">${esc(sync)}</p>${!cloud&&!demo?'<div class="notice" style="margin-bottom:16px">Accesso Firebase verificato. La seduta è salvata in questo browser: il tabellone separato funziona, ma altri dispositivi non sono sincronizzati. Riattiva Realtime Database e accedi nuovamente per collegarli.</div>':''}${btn('Configura Firebase','config')}<p class="muted" style="font-size:12px;line-height:1.8;margin-top:16px">Login email e password. Presidente: jacopo@ferrioli.eu. Segretari: amministrazione.generale@cas.ferrioli.eu e amministrazione@ferrioli.eu. Gli altri account accedono come votanti.</p><div class="notice">Per più dispositivi occorre un progetto Firebase con Authentication e Realtime Database configurati. La demo locale non collega computer diversi.</div></section>${demo?`<section class="card"><h2>Strumenti di prova</h2><p class="muted">Carica una seduta fittizia o prova le diverse interfacce.</p>${btn('Carica dati dimostrativi','seed')}${select('Ruolo demo','demoRole',Object.entries(roleNames),role)}${btn('Applica ruolo','demo-role','small')}</section>`:''}</div></div>`;}
function boardView(){return `<div class="page-head"><div><div class="eyebrow">STATO DI SEBORG · FERRIOLI.EU · SEDUTA ${state.number}</div><h1 class="board-title">${esc(state.title)}</h1><p>${esc(activeAgenda()?.title||'Lavori dell’Assemblea Parlamentare')}</p><span class="badge neutral" style="margin-top:12px">${state.status==='active'?'Seduta in corso':state.status==='suspended'?'Seduta sospesa':state.status==='ended'?'Seduta conclusa':'In attesa dell’apertura'}</span></div><div class="actions screen-only">${btn('Schermo intero','fullscreen')}${btn('Chiudi tabellone','close-board')}</div></div>${motion()?.phase==='published'?motionCard():`<div class="grid-main"><div>${speakerCard()}</div><div>${motionCard()}<div class="card"><span class="eyebrow">PRESENTI IN AULA</span><div class="stat-value">${counts().present} <small>/ ${counts().total}</small></div></div></div></div>`}`;}
function elapsed(s){return (s.elapsed||0)+(s.running?Date.now()-s.since:0);}
function duration(ms){const over=ms<0;const sec=Math.ceil(Math.abs(ms)/1000);return (over?'+':'')+String(Math.floor(sec/60)).padStart(2,'0')+':'+String(sec%60).padStart(2,'0');}
function tick(){if($('#clock'))$('#clock').textContent=new Date().toLocaleTimeString('it-IT');const s=state.speaker;if(s&&$('#speech-timer')){const remaining=s.limit-elapsed(s);$('#speech-timer').textContent=duration(remaining);$('#speech-timer').classList.toggle('over',remaining<0);$('#timer-hint').textContent=remaining<0?'TEMPO SUPERATO':s.running?'TEMPO RIMANENTE':'TIMER IN PAUSA';$('#timer-progress').style.width=Math.max(0,remaining/s.limit*100)+'%';}if($('#suspension-timer')){const left=state.resumeAt-Date.now();$('#suspension-timer').textContent=left>0?duration(left):'00:00';$('#suspension-info').textContent=left>0?'Ripresa prevista alle '+timeStr(state.resumeAt):'Orario di ripresa raggiunto · in attesa della presidenza';}}
setInterval(tick,250);
function renderOverlay(){if(modalKind)return;if(state.status==='suspended'&&user){$('#overlay').innerHTML=`<div class="modal-backdrop suspended"><section class="modal" role="dialog" aria-modal="true" aria-label="Seduta sospesa"><div class="eyebrow" style="color:#c2a36b">PARLAMENTO DELLO STATO DI SEBORG</div><h2>La seduta è sospesa.</h2><p id="suspension-info">Ripresa prevista alle ${timeStr(state.resumeAt)}</p><div class="timer" id="suspension-timer"></div><p>Gli interventi riprenderanno al rientro in aula.</p>${preside()?btn('Riprendi la seduta','resume','gold'):''}</section></div>`;tick();return;}const m=motion();if(user&&role==='voter'&&!board&&allowVoteOverlay&&m?.phase==='open'&&m.mode==='digital'&&state.status==='active'){votingOverlay(m);return;}$('#overlay').innerHTML='';}
function votingOverlay(m){const member=state.members.find(x=>x.email?.toLowerCase()===user.email?.toLowerCase());const eligible=member?.present&&member?.eligible;const existing=ballots[m.id]?.[user.uid];$('#overlay').innerHTML=`<div class="modal-backdrop"><section class="modal wide" role="dialog" aria-modal="true" aria-label="Esprimi il voto"><div class="modal-head"><span class="badge">Votazione aperta</span>${btn('✕','hide-vote','ghost','aria-label="Chiudi"')}</div><h2 class="motion-title">${esc(m.title)}</h2><p class="muted">Presentata da ${esc(m.presenter)} · Voto ${m.secret?'segreto':'palese'}</p>${eligible?`<div class="vote-grid">${OPTIONS.map(([key,label,short])=>btn(`<b>${key==='yes'?'✓':key==='no'?'✕':key==='abstain'?'—':key==='blank'?'□':'⊘'}</b>${short}`,'cast',`vote-option vote-${key} ${existing?.choice===key?'selected':''}`,`data-choice="${key}"`)).join('')}</div><div class="notice">${existing?'Voto registrato. Puoi modificarlo fino alla chiusura.':'Scegli un’opzione per registrare il voto.'} I risultati saranno visibili solo dopo la pubblicazione.</div>`:'<div class="notice">Per votare devi essere registrato in assemblea con questa email, presente e con diritto di voto. Contatta la segreteria.</div>'}</section></div>`;}
function snapshot(m){return m.attendance||counts();}
function threshold(m){const a=snapshot(m);if(m.rule==='absolute')return Math.floor(a.electorate/2)+1;if(m.rule==='qualified')return Math.ceil((m.base==='present'?a.eligible:a.electorate)*m.numerator/m.denominator);if(m.rule==='custom')return m.custom;return null;}
function ruleLabel(m){return m.rule==='simple'?'Semplice · sì > no':m.rule==='absolute'?'Assoluta dei componenti':m.rule==='qualified'?`${m.numerator}/${m.denominator} ${m.base==='present'?'dei presenti aventi diritto':'dei componenti aventi diritto'}`:`Soglia di ${m.custom} favorevoli`;}
function quorumThreshold(m){const a=snapshot(m);return m.quorum==='none'?0:m.quorum==='custom'?m.quorumValue:Math.floor(a.electorate/2)+1;}
function outcome(m){const r=m.result,a=snapshot(m),q=quorumThreshold(m);if(!r)return null;if(a.eligible<q)return {label:'Quorum non raggiunto',passed:false};if(!OPTIONS.reduce((s,[k])=>s+(+r[k]||0),0))return {label:'Nessun voto espresso',passed:false};const pass=m.rule==='simple'?r.yes>r.no:r.yes>=threshold(m);return {label:pass?'Mozione approvata':'Mozione respinta',passed:pass};}
function resultsHTML(m){const r=m.result;if(!r)return '';const a=snapshot(m),total=OPTIONS.reduce((s,[k])=>s+(+r[k]||0),0),o=outcome(m);return `<div class="badge ${o.passed?'':'amber'}">${o.label}</div><div class="result-bar">${OPTIONS.map(([k,l,sh,color])=>`<span style="background:${color};width:${total?r[k]/total*100:0}%"></span>`).join('')}</div><div class="result-stats">${OPTIONS.map(([k,l])=>`<div class="vote-${k}"><b>${r[k]}</b><small>${l}</small></div>`).join('')}</div><div class="meta section-gap"><div><small>TOTALE ESPRESSI / AVENTI DIRITTO PRESENTI</small>${total} / ${a.eligible}</div><div><small>SOGLIA RICHIESTA</small>${m.rule==='simple'?'Favorevoli > contrari':threshold(m)+' favorevoli'}</div><div><small>QUORUM</small>${a.eligible} presenti aventi diritto / ${quorumThreshold(m)} richiesti</div><div><small>NON VOTANTI</small>${a.eligible-total}</div></div>${!m.secret&&m.mode==='digital'?`<hr class="divider"><h3>Voto palese</h3>${Object.values(m.rollcall||{}).map(v=>`<div class="row"><div class="row-main">${esc(v.name)}</div><span class="pill vote-${v.choice}">${OPTIONS.find(o=>o[0]===v.choice)?.[2]}</span></div>`).join('')||'<p class="muted">Nessun voto individuale registrato.</p>'}`:''}`;}
function finishSpeech(){if(!state.speaker)return;const s=state.speaker;state.speeches.push({...s,actual:elapsed(s),ended:Date.now(),agendaTitle:activeAgenda()?.title||''});log('Termina l’intervento di '+s.name+' (posto '+(s.seat||'—')+').');state.speaker=null;}
function startSpeech(q){state.speaker={...q,started:Date.now(),since:Date.now(),elapsed:0,limit:q.minutes*60000,running:true};log('La parola è concessa a '+q.name+', posto '+(q.seat||'—')+'.');}
function speechForm(queue=false){openModal(queue?'Prenota un intervento':'Dai la parola',`<div class="form-grid">${field('Numero del posto','seat','text','','required')}${field('Nome o email (facoltativo)','name')}${field('Durata (minuti)','minutes','number',state.defaultMinutes,'min="0.1" step="0.1" required')}</div>`,queue?'Aggiungi alla coda':'Avvia intervento',queue?'queue-add':'give-floor');}
function agendaForm(id){const a=state.agenda.find(x=>x.id===id);openModal(a?'Modifica punto':'Nuovo punto all’ordine del giorno',`<input type="hidden" name="id" value="${a?.id||''}"><div class="form-grid"><div class="field full">${field('Titolo','title','text',a?.title||'','required')}</div>${area('Descrizione / note','description',a?.description||'')}</div>`,'Salva punto','agenda');}
function memberForm(id){const m=state.members.find(x=>x.id===id);openModal(m?'Modifica membro':'Aggiungi un membro',`<input type="hidden" name="id" value="${m?.id||''}"><div class="form-grid">${field('Nome e cognome','name','text',m?.name||'')}${field('Email','email','email',m?.email||'')}${field('Posto','seat','text',m?.seat||'')}<div></div>${check('Presente in aula','present',m?m.present:true)}${check('Con diritto di voto','eligible',m?m.eligible:true)}</div><p class="muted section-gap">È sufficiente il nome o l’email. Per votare dal proprio dispositivo serve l’email dell’account Firebase.</p>`,'Salva membro','member');}
function motionForm(id,parent){const m=state.motions.find(x=>x.id===id);openModal(m?'Modifica proposta':parent?'Nuovo emendamento':'Nuova mozione',`<input type="hidden" name="id" value="${m?.id||''}"><input type="hidden" name="parent" value="${m?.parent||parent||''}"><div class="form-grid"><div class="field full">${field('Titolo','title','text',m?.title||'','required')}</div>${area('Testo della proposta','text',m?.text||'')}${field('Presentatore','presenter','text',m?.presenter||'','required')}${field('Firmatari (separati da virgole)','signers','text',m?.signers||'')}${select('Modalità di raccolta','mode',[['manual','Inserimento manuale'],['digital','Voto dai dispositivi']],m?.mode||'manual')}${select('Visibilità del voto','visibility',[['public','Palese'],['secret','Segreto']],m?.secret?'secret':'public')}${select('Maggioranza richiesta','rule',[['simple','Semplice: favorevoli > contrari'],['absolute','Assoluta dei componenti aventi diritto'],['qualified','Qualificata (frazione)'],['custom','Numero minimo di favorevoli']],m?.rule||'simple')}${select('Base della maggioranza qualificata','base',[['electorate','Componenti aventi diritto'],['present','Presenti aventi diritto']],m?.base||'electorate')}${field('Frazione: numeratore','numerator','number',m?.numerator||2,'min="1" required')}${field('Frazione: denominatore','denominator','number',m?.denominator||3,'min="1" required')}${field('Soglia personalizzata di favorevoli','custom','number',m?.custom||1,'min="1" required')}${select('Quorum di validità','quorum',[['half','Più della metà dei componenti aventi diritto'],['none','Nessun quorum'],['custom','Numero personalizzato di presenti aventi diritto']],m?.quorum||'half')}${field('Quorum personalizzato','quorumValue','number',m?.quorumValue||1,'min="1" required')}</div><div class="notice section-gap">Presenze e aventi diritto sono fissati all’apertura della votazione. Astensioni, bianche e nulle non contano tra i favorevoli.</div>`,'Salva proposta','motion',true);}
function counted(m){const r=Object.fromEntries(OPTIONS.map(([k])=>[k,0]));for(const v of Object.values(ballots[m.id]||{}))if(v.choice in r)r[v.choice]++;return r;}
function resultForm(){const m=motion();if(!m||m.phase!=='pending')return;const r=m.result||(m.mode==='digital'?counted(m):{}),a=snapshot(m);openModal('Scrutinio della votazione',`<p class="muted">${esc(m.title)}</p><div class="notice">${a.eligible} presenti aventi diritto · quorum ${quorumThreshold(m)} · ${esc(ruleLabel(m))}</div><div class="form-grid section-gap">${OPTIONS.map(([k,l])=>field(l,k,'number',r[k]||0,`min="0" step="1" required ${m.mode==='digital'?'readonly':''}`)).join('')}</div><p id="result-total" class="muted section-gap"></p>${m.mode==='digital'?'<small>Il conteggio è ricavato dai voti registrati. Il voto palese conserva l’elenco nominativo.</small>':'<small>Il totale può essere inferiore agli aventi diritto: i restanti sono non votanti.</small>'}`,'Conferma scrutinio','results');updateResultTotal();}
function updateResultTotal(){if(modalKind!=='results')return;const form=$('#modal-form');const total=OPTIONS.reduce((s,[k])=>s+(+form.elements[k].value||0),0);$('#result-total').textContent='Totale inserito: '+total+' / '+snapshot(motion()).eligible+' aventi diritto presenti';}
function configForm(){const cfg=firebaseConfig();openModal('Collega Firebase',`<p class="muted">Incolla l’oggetto JSON della configurazione web Firebase. Non inserire chiavi private o account di servizio.</p>${area('firebaseConfig (JSON)','config',cfg?JSON.stringify(cfg,null,2):'')}<div class="notice section-gap">Occorrono apiKey, authDomain, projectId e databaseURL. Attiva Email/Password in Authentication e configura Realtime Database. Usa un progetto di prova: tutte le sessioni dell’app condividono il percorso aula.</div>`,'Salva configurazione','config');}
function minutesView(){return head('Verbale della seduta','Un resoconto essenziale, pronto da conservare.',btn('↓ Salva come PDF','print','primary'))+`<article class="document"><div class="doc-top"><div class="eyebrow">STATO DI SEBORG · VERBALE PARLAMENTARE</div><h1>${esc(state.title)}</h1><p>Seduta n. ${state.number} · ${dateStr(state.date)}<br>Apertura: ${state.started?timeStr(state.started):'non ancora aperta'} · Chiusura: ${state.ended?timeStr(state.ended):'seduta non conclusa'}</p></div><h2>1. Composizione e presenze</h2><p>Situazione ${state.ended?'alla chiusura':'attuale'}: ${counts().present} presenti, ${counts().absent} assenti. Presenti con diritto di voto: ${counts().eligible}; senza diritto: ${counts().nonVoting}.</p><p>${state.members.map(m=>esc(m.name||m.email)+' — '+(m.present?'presente':'assente')+(m.eligible?'':' (senza diritto di voto)')).join('; ')||'Nessun membro registrato.'}</p><h2>2. Ordine del giorno</h2><ol>${state.agenda.map(a=>`<li><strong>${esc(a.title)}</strong>${a.description?': '+esc(a.description):''} — ${a.done?'concluso':a.id===state.currentAgenda?'in discussione':'da discutere'}</li>`).join('')||'<li>Nessun punto registrato.</li>'}</ol><h2>3. Interventi</h2>${state.speeches.length?`<table><thead><tr><th>Ora</th><th>Oratore / posto</th><th>Durata</th><th>Argomento</th></tr></thead><tbody>${state.speeches.map(s=>`<tr><td>${timeStr(s.started)}</td><td>${esc(s.name)} / ${esc(s.seat||'—')}</td><td>${duration(s.actual)}</td><td>${esc(s.agendaTitle)}</td></tr>`).join('')}</tbody></table>`:'<p>Nessun intervento concluso.</p>'}${state.speaker?'<p>Intervento in corso: '+esc(state.speaker.name)+'. Sarà incluso dopo la conclusione.</p>':''}<h2>4. Mozioni e votazioni</h2>${state.motions.map((m,i)=>`<section><h3>${i+1}. ${m.parent?'Emendamento: ':''}${esc(m.title)}</h3><p>${esc(m.text).replace(/\n/g,'<br>')}<br>Presentatore: ${esc(m.presenter)}. Firmatari: ${esc(m.signers||'nessuno')}.<br>${ruleLabel(m)} · Voto ${m.secret?'segreto':'palese'}.</p>${m.phase==='published'?`<p><strong>${outcome(m).label}.</strong> ${OPTIONS.map(([k,l])=>l+': '+m.result[k]).join(' · ')}.<br>Aventi diritto presenti: ${snapshot(m).eligible}; componenti aventi diritto: ${snapshot(m).electorate}; quorum richiesto: ${quorumThreshold(m)}; soglia: ${m.rule==='simple'?'favorevoli > contrari':threshold(m)}.</p>${!m.secret&&m.mode==='digital'?'<p>Voti palesi: '+Object.values(m.rollcall||{}).map(v=>esc(v.name)+' — '+OPTIONS.find(o=>o[0]===v.choice)?.[2]).join('; ')+'.</p>':''}`:`<p>Stato: ${phaseNames[phases.indexOf(m.phase)]}. Risultati non pubblicati.</p>`}</section>`).join('')||'<p>Nessuna mozione registrata.</p>'}<h2>5. Cronologia della seduta</h2>${state.log.map(e=>`<p style="margin:4px 0"><strong>${timeStr(e.at)}</strong> — ${esc(e.text)}</p>`).join('')||'<p>Nessuna attività registrata.</p>'}<h2>6. Note della segreteria</h2><p style="white-space:pre-wrap">${esc(state.notes||'Nessuna annotazione.')}</p>${manage()?btn('Modifica note','notes','screen-only small'):''}<div style="display:flex;justify-content:space-between;margin-top:60px;font-size:12px"><span>Il presidente<br><br>___________________</span><span>Il segretario<br><br>___________________</span></div></article>`;}
const restricted={president:['start','suspend','resume','end','give-floor','queue-start','timer-toggle','timer-add','speech-end','agenda-discuss','agenda-done','vote-open','vote-close','vote-pending','vote-publish','new-session'],manager:['queue-add','queue-remove','agenda-add','agenda-edit','member-add','member-edit','motion-add','motion-edit','amendment-add','results','notes']};
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const action=b.dataset.action,id=b.dataset.id;if(restricted.president.includes(action)&&!preside())return;if(restricted.manager.includes(action)&&!manage())return;const m=motion();switch(action){case 'demo':enterDemo();break;case 'nav':page=b.dataset.page;render();break;case 'close':closeModal();break;case 'config':configForm();break;case 'logout':if(auth)await fb.signOut(auth);user=null;role=null;demo=false;board=false;unsubscribe?.();unballots?.();cloud=null;render();break;case 'board':openBoard();break;case 'close-board':window.close();break;case 'fullscreen':if(document.fullscreenElement)document.exitFullscreen();else document.documentElement.requestFullscreen().catch(()=>toast('Usa il comando Schermo intero del browser.'));break;case 'start':state.status='active';state.started=Date.now();log('La presidenza dichiara aperta la seduta. Presenti: '+counts().present+'.');save();break;case 'suspend':openModal('Sospendi la seduta',`<div class="form-grid">${field('Ripresa tra (minuti)','minutes','number',10,'min="1" required')}${field('Oppure alle ore','time','time')}</div>`,'Sospendi','suspend');break;case 'resume':state.status='active';state.resumeAt=null;log('La seduta riprende. Il timer dell’intervento resta in pausa.');save();break;case 'end':openModal('Concludi la seduta','<p>Il verbale rimarrà disponibile. Concludi prima tutte le votazioni aperte o in scrutinio.</p>','Concludi seduta','end');break;case 'give-floor':speechForm();break;case 'queue-add':speechForm(true);break;case 'queue-remove':state.queue=state.queue.filter(q=>q.id!==id);save();break;case 'queue-start':{if(state.speaker||state.status!=='active')return;const q=state.queue.find(q=>q.id===id);startSpeech(q);state.queue=state.queue.filter(q=>q.id!==id);save();break;}case 'timer-toggle':if(!state.speaker||state.status!=='active')return;state.speaker.elapsed=elapsed(state.speaker);state.speaker.since=Date.now();state.speaker.running=!state.speaker.running;save();break;case 'timer-add':if(state.speaker){state.speaker.limit+=30000;save();}break;case 'speech-end':finishSpeech();save();break;case 'agenda-add':agendaForm();break;case 'agenda-edit':agendaForm(id);break;case 'agenda-discuss':state.currentAgenda=id;log('Si apre la discussione: '+activeAgenda().title+'.');save();break;case 'agenda-done':{const a=state.agenda.find(a=>a.id===id);a.done=true;if(state.currentAgenda===id)state.currentAgenda=null;log('Concluso il punto: '+a.title+'.');save();break;}case 'member-add':memberForm();break;case 'member-edit':memberForm(id);break;case 'motion-add':motionForm();break;case 'motion-edit':motionForm(id);break;case 'amendment-add':motionForm(null,m?.parent||m?.id);break;case 'motion-select':{const live=state.motions.find(x=>['open','closed','pending'].includes(x.phase));if(live&&live.id!==id){toast('Completa la votazione in corso prima di cambiare proposta.');return;}state.selectedMotion=id;if(manage())save();else render();break;}case 'vote-open':if(m?.phase!=='preparation'||state.status!=='active')return;if(state.motions.some(x=>x.id!==m.id&&['open','closed','pending'].includes(x.phase)))return toast('Completa prima la votazione in corso.');if(!counts().eligible)return toast('Registra almeno un presente avente diritto.');m.attendance=counts();m.phase='open';m.opened=Date.now();log('Aperta la votazione su «'+m.title+'».');save();break;case 'vote-close':if(m?.phase!=='open')return;m.phase='closed';m.closed=Date.now();log('Chiusa la votazione su «'+m.title+'».');save();break;case 'vote-pending':if(m?.phase!=='closed')return;m.phase='pending';await save();resultForm();break;case 'results':resultForm();break;case 'vote-publish':if(m?.phase!=='pending'||!m.result)return;m.phase='published';m.published=Date.now();log('Pubblicato l’esito di «'+m.title+'»: '+outcome(m).label+'.');save();break;case 'hide-vote':allowVoteOverlay=false;renderOverlay();break;case 'vote-show':allowVoteOverlay=true;renderOverlay();break;case 'cast':await castVote(b.dataset.choice);break;case 'print':page='minutes';render();window.print();break;case 'notes':openModal('Note per il verbale',area('Annotazioni','notes',state.notes),'Salva note','notes');break;case 'new-session':openModal('Inizia una nuova seduta','<p>La seduta corrente sarà sostituita. Salva prima il verbale in PDF. I membri saranno mantenuti.</p>','Crea nuova seduta','new-session');break;case 'seed':openModal('Carica la seduta dimostrativa','<p>I dati correnti della demo saranno sostituiti da un’assemblea fittizia.</p>','Carica esempio','seed');break;case 'demo-role':if(demo){role=$('[name=demoRole]').value;user.uid='demo-'+role;user.email=role==='voter'?'votante@example.test':'demo@locale';allowVoteOverlay=true;render();}break;}});
document.addEventListener('change',e=>{if(e.target.dataset.member&&manage()){const m=state.members.find(m=>m.id===e.target.dataset.member);m[e.target.dataset.prop]=e.target.checked;log('Aggiornato membro '+(m.name||m.email)+': '+(m.present?'presente':'assente')+', '+(m.eligible?'con':'senza')+' diritto di voto.');save();}});
document.addEventListener('input',()=>updateResultTotal());
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target;if(form.id==='login-form'){await login(form);return;}const action=form.dataset.submit,f=Object.fromEntries(new FormData(form));try{switch(action){case 'config':{const c=JSON.parse(f.config);if(!c.apiKey||!c.authDomain||!c.projectId||!c.databaseURL)throw Error('Inserisci apiKey, authDomain, projectId e databaseURL.');if(!/^https:\/\//.test(c.databaseURL))throw Error('databaseURL deve iniziare con https://.');localStorage.setItem(KEYS.config,JSON.stringify(c));closeModal();toast('Configurazione salvata. Esci dalla demo per accedere con Firebase.');render();return;}case 'settings':if(!manage())return;state.title=f.title.trim();state.number=+f.number;state.defaultMinutes=+f.minutes;break;case 'give-floor':case 'queue-add':{if(!manage())return;if(action==='give-floor'&&(!preside()||state.status!=='active'||state.speaker))throw Error('La parola è già assegnata oppure la seduta non è attiva.');const member=state.members.find(x=>x.seat===f.seat.trim());const q={id:uuid(),seat:f.seat.trim(),name:f.name.trim()||member?.name||member?.email||'Posto '+f.seat.trim(),minutes:+f.minutes};if(action==='queue-add')state.queue.push(q);else startSpeech(q);break;}case 'agenda':if(!manage())return;{const a=state.agenda.find(x=>x.id===f.id);if(a)Object.assign(a,{title:f.title.trim(),description:f.description});else state.agenda.push({id:uuid(),title:f.title.trim(),description:f.description,done:false});break;}case 'member':{if(!manage())return;if(!f.name.trim()&&!f.email.trim())throw Error('Inserisci almeno un nome o un’email.');if(f.email&&state.members.some(x=>x.id!==f.id&&x.email?.toLowerCase()===f.email.toLowerCase()))throw Error('Questa email è già presente.');const data={id:f.id||uuid(),name:f.name.trim(),email:f.email.trim().toLowerCase(),seat:f.seat.trim(),present:f.present==='on',eligible:f.eligible==='on'},existing=state.members.find(x=>x.id===f.id);if(existing)Object.assign(existing,data);else state.members.push(data);break;}case 'motion':{if(!manage())return;if(+f.numerator>+f.denominator)throw Error('La frazione di maggioranza non può superare 1.');const data={id:f.id||uuid(),parent:f.parent||null,title:f.title.trim(),text:f.text,presenter:f.presenter.trim(),signers:f.signers,mode:f.mode,secret:f.visibility==='secret',rule:f.rule,base:f.base,numerator:+f.numerator,denominator:+f.denominator,custom:+f.custom,quorum:f.quorum,quorumValue:+f.quorumValue};const existing=state.motions.find(x=>x.id===f.id);if(existing){if(existing.phase!=='preparation')throw Error('La votazione è già iniziata.');Object.assign(existing,data);}else {state.motions.push({...data,phase:'preparation'});if(!state.motions.some(x=>['open','closed','pending'].includes(x.phase)))state.selectedMotion=data.id;}break;}case 'suspend':{if(!preside())return;let until=Date.now()+(+f.minutes)*60000;if(f.time){const [h,min]=f.time.split(':').map(Number);const dt=new Date();dt.setHours(h,min,0,0);if(dt.getTime()<=Date.now())dt.setDate(dt.getDate()+1);until=dt.getTime();}if(state.speaker){state.speaker.elapsed=elapsed(state.speaker);state.speaker.running=false;}state.status='suspended';state.resumeAt=until;log('Seduta sospesa. Ripresa prevista alle '+timeStr(until)+'.');break;}case 'end':if(!preside())return;if(state.motions.some(x=>['open','closed','pending'].includes(x.phase)))throw Error('Concludi e pubblica prima la votazione in corso.');finishSpeech();state.status='ended';state.ended=Date.now();log('La presidenza dichiara conclusa la seduta.');break;case 'results':{if(!manage())return;const m=motion();if(m.phase!=='pending')throw Error('Lo scrutinio non è più aperto.');const r=m.mode==='digital'?counted(m):Object.fromEntries(OPTIONS.map(([k])=>[k,+f[k]]));if(Object.values(r).some(v=>!Number.isInteger(v)||v<0))throw Error('Inserisci numeri interi non negativi.');const total=Object.values(r).reduce((a,b)=>a+b,0);if(total>snapshot(m).eligible)throw Error('Il totale ('+total+') supera i presenti aventi diritto ('+snapshot(m).eligible+').');m.result=r;if(m.mode==='digital'&&!m.secret)m.rollcall=ballots[m.id]||{};toast('Scrutinio salvato. La presidenza può pubblicare i risultati.');break;}case 'notes':if(!manage())return;state.notes=f.notes;break;case 'new-session':{if(!preside())return;const members=state.members,number=state.number+1,title=state.title;state=initial();state.members=members;state.number=number;state.title=title;page='dashboard';break;}case 'seed':if(!demo)return;seed();break;default:return;}modalKind='';$('#overlay').innerHTML='';await save();}catch(err){if($('#form-error'))formError(err.message);else toast(err.message);}});
async function castVote(choice){const m=motion(),member=state.members.find(x=>x.email===user.email?.toLowerCase());if(!m||m.phase!=='open'||state.status!=='active'||!member?.present||!member?.eligible||!OPTIONS.some(o=>o[0]===choice))return;const v={choice,name:member.name||member.email,at:Date.now()};try{if(cloud)await fb.set(fb.ref(cloud,`aula/ballots/${m.id}/${user.uid}`),v);else{ballots=read(KEYS.ballots,{});ballots[m.id]??={};ballots[m.id][user.uid]=v;localStorage.setItem(KEYS.ballots,JSON.stringify(ballots));}toast('Voto registrato.');renderOverlay();}catch(e){toast('Voto non registrato: '+e.message);}}
async function login(form){
  const err=$('#login-error'),button=form.querySelector('button');
  button.disabled=true;err.textContent='Accesso a FERRIOLI.EU…';
  try{
    const config=firebaseConfig();if(!config)throw Error('Configura prima Firebase.');
    if(!fb){
      const modules=await Promise.all([
        import('https://www.gstatic.com/firebasejs/11.10.0/firebase-app.js'),
        import('https://www.gstatic.com/firebasejs/11.10.0/firebase-auth.js'),
        import('https://www.gstatic.com/firebasejs/11.10.0/firebase-database.js')
      ]);
      fb=Object.assign({},...modules);
    }
    const app=fb.getApps().find(a=>a.name===config.projectId)||fb.initializeApp(config,config.projectId);
    auth=fb.getAuth(app);
    const result=await fb.signInWithEmailAndPassword(auth,form.elements.email.value.trim(),form.elements.password.value);
    user=result.user;role=roleOf(user.email);demo=false;
    state=normalize(read(KEYS.state,null)||initial());ballots=read(KEYS.ballots,{});
    sync='Accesso verificato · collegamento alla seduta…';render();
    let deadline;
    const database=fb.getDatabase(app),ref=fb.ref(database,'aula/session');
    try{
      const snap=await Promise.race([
        fb.get(ref),
        new Promise((_,reject)=>{deadline=setTimeout(()=>reject(Error('Database non raggiungibile')),7000);})
      ]);
      clearTimeout(deadline);
      if(snap.exists())state=normalize(snap.val());
      // Il collegamento non crea né sovrascrive sedute: la prima modifica della regia le salva.
      cloud=database;sync='Connesso · aggiornamenti in tempo reale';
      unsubscribe=fb.onValue(ref,s=>{
        if(s.exists()){state=normalize(s.val());localStorage.setItem(KEYS.state,JSON.stringify(state));render();}
      },()=>{
        unsubscribe?.();unballots?.();cloud=null;sync='Accesso verificato · seduta locale';
        toast('Database non disponibile: prosegui in locale. Il tabellone resta collegato.');render();
      });
      unballots=fb.onValue(fb.ref(database,'aula/ballots'),s=>{
        ballots=s.val()||{};localStorage.setItem(KEYS.ballots,JSON.stringify(ballots));
        if(motion()?.phase==='open')renderOverlay();
      },()=>toast('Impossibile sincronizzare i voti. Verifica il database Firebase.'));
    }catch(e){
      clearTimeout(deadline);cloud=null;sync='Accesso verificato · seduta locale';
      toast('Database non disponibile: presidenza e tabellone funzionano in locale.');
    }
    render();
  }catch(e){
    user=null;role=null;cloud=null;render();
    $('#login-error').textContent='Accesso non riuscito. '+(e.code==='auth/invalid-credential'?'Email o password non corretti.':e.message);
    $('#login-form button').disabled=false;
  }
}

function seed(){state=initial();state.title=ASSEMBLY_NAME;state.status='active';state.started=Date.now();state.members=Array.from({length:24},(_,i)=>({id:uuid(),name:i===0?'Jacopo Ferrioli':i===1?'Votante dimostrativo':'Componente '+String(i+1).padStart(2,'0'),email:i===1?'votante@example.test':'',seat:String(i+1),present:i<21,eligible:i!==20}));state.agenda=[{id:uuid(),title:'Comunicazioni della presidenza',description:'Apertura dei lavori e approvazione dell’ordine del giorno.',done:true},{id:uuid(),title:'Proposta per le iniziative dello Stato',description:'Discussione delle proposte presentate dai membri del Parlamento.',done:false},{id:uuid(),title:'Calendario delle prossime assemblee',description:'Definizione delle date e dei temi.',done:false},{id:uuid(),title:'Varie ed eventuali',description:'Interventi conclusivi.',done:false}];state.currentAgenda=state.agenda[1].id;state.queue=[{id:uuid(),name:'Componente 07',seat:'7',minutes:3},{id:uuid(),name:'Componente 12',seat:'12',minutes:2}];const m={id:uuid(),title:'Istituzione di una giornata dedicata alle associazioni',text:'L’assemblea propone una giornata di incontro con le associazioni del territorio, aperta alla cittadinanza, per promuovere partecipazione e volontariato.',presenter:'Jacopo Ferrioli',signers:'Componente 04, Componente 09',phase:'preparation',mode:'manual',secret:false,rule:'simple',base:'electorate',numerator:2,denominator:3,custom:1,quorum:'half',quorumValue:1};state.motions=[m];state.selectedMotion=m.id;log('Apertura della seduta dimostrativa.');startSpeech({id:uuid(),name:'Componente 03',seat:'3',minutes:3});page='dashboard';}
render();
